  }

    render() {
        return (
    <div>
        <Row gutter={15}  justify="space-between" align="middle">
                <Col span={12}  style={{paddingTop:10,paddingRight:5}} md={{span:12}} lg={{span:8}}>
                    <Card >
                    <Avatar style={{ color: '#2d1582' }} icon="transaction" />
                            <h6 style={{color:"#2d1582"}}>Amount Transacted</h6>
                    {/* <p>{this.state.amounttransacted} ETH</p> */}
                    </Card>

                </Col>
                <Col span={12} style={{paddingTop:10,paddingRight:5}} md={{span:12}} lg={{span:8} }>

                    <Card


                        >
                            <h6 style={{color:"#2d1582"}}>Number of Transactions</h6>

                             <p>{this.state.transactions}</p>
                    </Card>

                </Col>
                <Col   style={{paddingTop:10,paddingRight:5}} span={12} md={{span:12}} lg={{span:8}}>		
                <Card   
						 hoverable className="dashCard" bordered={false} style={{padding:0, marginBottom:15}}>
                    <strong>
					   <h6 style={{color:"#2d1582"}}>Number of Orders</h6>
					</strong>
					{/* {this.state.wallets.map((item, key) => (
                   <Popover content={item.walletAdress} title="Wallet Adress">
	                  <p   onClick={() => {navigator.clipboard.writeText(item.walletAdress)}} style={{color:'#555555'}}>{item.walletName}:{item.walletAdress}</p>
					  </Popover>
					   ))}	 	    */}
                </Card>
            </Col>
        </Row>

    </div>
        );
    }
}
export default (Dashboard);
